float timeDifference = (enemyPath[1].t - currentTime) / enemyPath[1].duration;

// Calculate the distance between the current position and the interpolated position
float distance = (enemyPath[1].position - currentPosition).magnitude;

// Use the time difference and distance to calculate the likelihood of the enemy following the path
float likelihood = (timeDifference > 0? 1 - (distance / enemyPath[1].duration) : 0);

// Convert the likelihood to a hitchance value between 0.1 and 1
float hitchance = likelihood * 100;

if (hitchance > 90) { // Cast the spell if the hitchance is higher than 90%
  // Cast the spell
} else { // Don't cast the spell if the hitchance is lower than 10%
  // Don't cast the spell
}
