        GroovyObject script = new GroovyObject();
        // Set the script's properties
        script.setProperty("message", "Hello, world!");
        script.setProperty("source", "HelloWorld.groovy");
        script.setProperty("script", "HelloWorld.groovy");

        // Execute the script
