Here is an example of a Swift function that takes an if-domain value from a Safari content blocker definition and translates it to the equivalent if-top-url value:
```
func translateIfDomainToIfTopURL(ifDomain: String) -> String {
    let ifTopURLRules = ["<all_urls>" : "if-top-url"]
    let ifDomainPattern = "\\bif-domain\\b"
    let domainPattern = "\\b(\\w+)\\b"
    let domainCapture = "(?:"
    for (key, value) in ifTopURLRules {
        let keyPattern = "\\b" + key + "\\b"
        let valuePattern = "\\b" + value + "\\b"
        domainCapture += "(" + keyPattern + "|" + valuePattern + ")"
        if domainPattern!= "\\b" {
            domainCapture += "|"
        }
    }
    let domainCaptureEnd = ")"
    let regex = "\\bif-domain\\b\\s*\\(" + domainCapture + "\\s*\\)" + domainCaptureEnd
    let domainMatch = regex.wmf_regexp_firstMatch(in: ifDomain)
    if domainMatch!= nil {
        let domain = domainMatch?.value(forKey: "domain") as? String
        let ifTopURL = ifTopURLRules[value(forKey: "if-top-url")] as? String
        return "if-top-url(\(ifTopURL))"
    }
    return ""
}
```
This function uses regular expressions to extract the domain from the if-domain value and match it with the corresponding if-top-url value, and returns the if-top-url value as a string. It uses the `wmf_regexp_firstMatch` function from the `WMFRegularExpression` class to find the first match of the regular expression pattern in the input string.

