            ftp.delete(f"{path}/{name}")
        elif properties['type'] == 'dir':
            print("Remove dir:", f"{path}/{name}")
            ftp_remove_dir(ftp, f"{path}/{name}")
    print("Remove final dir: ", path)
    ftp.rmd(path)
