Here is an example of a simple hash table implementation in C:
```
#include <stdio.h>
#include <stdlib.h>

#define TABLE_SIZE 100

typedef struct {
    int key;
    int value;
} HashEntry;

HashEntry table[TABLE_SIZE];

void hash_function(int key) {
    return key % TABLE_SIZE;
}

int get_hash_value(int key) {
    return hash_function(key);
}

int main() {
    HashEntry* old_table = table;
    table = (HashEntry*) malloc(TABLE_SIZE * sizeof(HashEntry));
    for (int i = 0; i < TABLE_SIZE; i++) {
        table[i].key = -1;
    }
    table[get_hash_value(1)].key = 1;
    table[get_hash_value(2)].key = 2;
    table[get_hash_value(3)].key = 3;

    for (int i = 0; i < TABLE_SIZE; i++) {
        printf("%d ", table[i].key);
    }
    printf("\n");

    free(old_table);
    return 0;
}
```
In this example, the `table` array serves as the hash table, and the `HashEntry` structure is used to store the key-value pairs. The `hash_function` is a simple hash function that takes an integer key and returns an index in the range of 0 to `TABLE_SIZE - 1`. The `get_hash_value` function takes an integer key and returns the corresponding index. The `table` array is initialized with all key-value pairs, and the hash function is used to map the keys to their corresponding indices in the array.

