Here is a Java code that generates a SQL query string like the one you described, given a start date and an end date:
```
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.Date;

public class SQLQueryGenerator {
    public static String generateSQLQuery(String startDate, String endDate) {
        // Start date format: yyyy-mm-dd
        Date startDateObj = parseDate(startDate);
        // End date format: yyyy-mm-dd
        Date endDateObj = parseDate(endDate);

        String sqlQuery = "SELECT * FROM table_name WHERE year = '"+startDateObj.getYear()+"' AND (month = '"+startDateObj.getMonth()+"' AND day >= '"+startDateObj.getDate()+"' AND day <= '"+endDateObj.getDate()+"') OR (year = '"+endDateObj.getYear()+"' AND month = '"+endDateObj.getMonth()+"' AND day >= '"+endDateObj.getDate()+"' AND day <= '"+endDateObj.getDate()+"')";
        return sqlQuery;
    }

    private static Date parseDate(String date) {
        Date dateObj = null;
        try {
            DateFormat format = new SimpleDateFormat("yyyy-MM-dd");
            dateObj = format.parse(date);
        } catch (Exception e) {
            System.out.println("Invalid date format");
        }
        return dateObj;
    }
}
```
