```less
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:flutter_bloc_plus/flutter_bloc_plus.dart';
import 'package:num_plus/num_plus.dart';

class CountBloc extends Bloc<CountEvent, CountState> {
  final countRepository;

  CountBloc({required this.countRepository});

  @override
  Stream<CountState> mapEventToState(CountEvent event) async * {
    final num = await countRepository.getNum();
    final newCount = event.num.add(num);
    emit CountUpdated(newCount);
  }
}

class CountRepository {
  final countProvider;

  CountRepository({required this.countProvider});

  Future<int> getNum() async {
    final num = await countProvider.getNum();
    return num;
  }
}

class CountProvider {
  final numProvider;

  CountProvider({required this.numProvider});

  Future<int> getNum() async {
    final num = await numProvider.getNum();
    return num;
  }
}

