ROS (Robot Operating System) is a middleware software framework that allows robots to communicate and coordinate with each other. A ROS node is a software component that runs on a robot and communicates with other nodes in the ROS system. Here is an example of a simple ROS node in C++:

```cpp
#include <ros/ros.h>

// Define a custom message type
class MyMessage
{
public:
    // Constructor
    MyMessage() {}

    // Definition of the message fields
    float data;
};

// Define a callback function to handle messages
void handle_message(const MyMessage& msg)
{
    // Do something with the message data
    ROS_INFO("Received message: data = [%f]", msg.data);
}

int main(int argc, char** argv)
{
    // Initialize ROS node
    ros::init(argc, argv, "my_node");

    // Publish a message
    ros::Publisher pub = ros::Publisher("my_topic", MyMessage, MyMessage::class);
    pub.publish(MyMessage());

    // Subscribe to a topic
    ros::Subscriber sub = ros::Subscriber("my_topic", MyMessage, MyMessage::class);
    sub.connect();
    sub.waitForMessage();
    MyMessage msg;
    sub.parseMessage(msg);
    ROS_INFO("Received message: data = [%f]", msg.data);

    // Clean up ROS node
    ros::shutdown();

    return 0;
}
```

This code sets up a ROS node that publishes a message on a topic and subscribes to another topic to receive messages. The custom message type `MyMessage` defines the structure of the message data, and the `handle_message` function is a callback function that is called when a message is received.

Here is an example of a limit order book implemented in Python that supports market orders, limit orders, and stop loss orders:

```
import math

class Exchange:
    def __init__(self, symbol, price, shares, order_book):
        self.symbol = symbol
        self.price = price
        self.shares = shares
        self.order_book = order_book

    def buy(self, amount):
        # Try to fill the order from the order book
        for order in self.order_book.buy:
            if order.shares >= amount:
                # Fill the order
                filled_shares = min(amount, order.shares)
                self.price = max(self.price, order.price)
                self.shares -= filled_shares
                self.order_book.sell(order.shares - filled_shares)
                return filled_shares
        # If the order cannot be filled from the order book, place a market order
        order = MarketOrder("buy", amount, self.symbol)
        order.execute()

    def sell(self, amount):
        # Try to fill the order from the order book
        for order in self.order_book.sell:
            if order.shares >= amount:
                # Fill the order
                filled_shares = min(amount, order.shares)
                self.price = max(self.price, order.price)
                self.shares += filled_shares
                self.order_book.buy(filled_shares)
                return filled_shares
        # If the order cannot be filled from the order book, place a market order
        order = MarketOrder("sell", amount, self.symbol)
        order.execute()

    def execute_order(self, order):
        if order.type == "market":
            order.price = self.price
        elif order.type == "limit":
            order.price = self.price
            if order.price < order.limit_price:
                order.status = "executed"
        elif order.type == "stop_loss":
            order.price = self.price
            if order.price < order.limit_price:
                order.status = "executed"
        else:
            raise ValueError("Invalid order type")
        return order

class OrderBook:
    def __init__(self):
        self.buy = []
        self.sell = []

    def add_buy_order(self, order):
        self.buy.append(order)

    def remove_buy_order(self, order):
        self.buy.remove(order)

    def add_sell_order(self, order):
        self.sell.append(order)

    def remove_sell_order(self, order):
        self.sell.remove(order)

    def get_buy_orders(self):
        return self.buy

    def get_sell_orders(self):
        return self.sell

class MarketOrder:
    def __init__(self, type, amount, symbol):
        self.type = type
        self.amount = amount
        self.symbol = symbol
        self.price = None
        self.status = None

    def execute(self):
        # Try to execute the order as a market order
        order = self.type + "_order"
        if self.type == "buy":
            order = Exchange("buy", self.symbol, self.amount, self.price, self.symbol)
        else:
            order = Exchange("sell", self.symbol, self.amount, self.price, self.symbol)
        order.execute()
```

