Here's a JavaScript function that takes an array of boolean flags and packs them into an hexadecimal string:

```javascript
function packBooleanFlags(flags) {
  let hexString = "";
  for (let i = 0; i < flags.length; i++) {
    if (flags[i]) {
      hexString += flags[i] + "";
    }
  }
  return hexString.toLowerCase();
}
```

And here's a function that takes an hexadecimal string and unpacks it back into an array of boolean flags:

```javascript
function unpackBooleanFlags(hexString) {
  let flags = [];
  let hex = hexString.replace(/(0|1)/g, (match) => {
    return match === "0" ? false : true;
  });
  let hexChars = hex.replace(/\w/g, (match) => {
    return match.charCodeAt(0) - 64;
  }).map((char) => {
    return char < 16 ? char.toString(16) : "0".charCodeAt(0).toString(16);
  });
  let index = 0;
  for (let len = hexChars.length; index < len; index++) {
    if (hexChars[index] !== "0") {
      flags.push(true);
    }
  }
  return flags;
}
```

For example, if you want to pack the boolean flags `true, true, false, true, true, false` into an hexadecimal string, you can use the `packBooleanFlags` function like this:

