Sure, here's an example method in C# that takes an integer and returns a list of prime numbers less than or equal to that integer:

```csharp
using System;
using System.Collections.Generic;

namespace PrimeNumbers
{
    class Program
    {
        static void Main(string[] args)
        {
            int n = 10;
            List<int> primes = GetPrimesUnderN(n);
            foreach (int prime in primes)
            {
                Console.WriteLine(prime);
            }
        }

        static List<int> GetPrimesUnderN(int n)
        {
            List<int> primes = new List<int>();
            bool[] sieve = new bool[n + 1];
            for (int i = 2; i <= n; i++)
            {
                sieve[i] = true;
            }
            for (int i = 2; i <= n / 2; i++)
            {
                if (sieve[i])
                {
                    for (int j = i + 1; j <= n; j++)
                    {
                        sieve[j] = false;
                    }
                }
            }
            for (int i = 2; i <= n; i++)
            {
                if (sieve[i])
                {
                    primes.Add(i);
                }
            }
            return primes;
        }
    }
}
```

This method uses the Sieve of Eratosthenes algorithm to generate a list of prime numbers less than or equal to the input value.

