Here is an example of a function that queries a MySQL database in Rust using the `mysql_driver` crate:
```rust
use mysql_driver::{
    Client,
    Result,
};

async fn query_mysql(query: &str) -> Result<String> {
    let client = Client::connect("localhost", "root", "password").await?;
    let stmt = client
       .prepare(query)
       .await?;
    let result = stmt.execute().await?;
    stmt.fetch_all().await?;
    let mut values = Vec::new();
    for (name, value) in stmt.result_metadata() {
        values.push(format!("{}: {}", name, value));
    }
    Ok(values.join(", "))
}
```
