Here is an example of C++ code that fetches a website and prints the document title:


```#include <iostream>
#include <string>
#include <curl/curl.h>

using namespace std;

int main() {
    CURL *curl;
    CURLcode res;
    string url = "https://www.example.com/";
    string title;

    curl = curl_easy_init();
    if (curl) {
        res = curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_FAILONERROR, 1);
        res = curl_easy_perform(curl);
        curl_easy_cleanup(curl);

        if (res == CURLE_OK) {
            title = curl_easy_getinfo(curl, CURLINFO_TITLE);
            }
    }

    cout << "Title: " << title << endl;

    return 0;
}
```

