```python
import os
import json
import git

def get_repositories(path):
    repositories = {}
    for root, dirs, files in os.walk(path):
        for filename in files:
            if filename.endswith(".git"):
                repository = git.Repo(os.path.join(root, filename))
                namespace = repository.commit.prefix
                branches = repository.branches.names
                # get current branch
                current_branch = repository.active_branch
                # add repository to map
                repositories[filename] = {
                    "namespace": namespace,
                    "branches": branches,
                    "current_branch": current_branch
                }
    return repositories

