    def __str__(self):
        result = []
        for i in range(self.iteration):
            if i > 0:
                result.append(' ')
            result.append(str(self.state[i]))
        return''.join(result)

    def set_state(self, state):
        self.state = state
        self.iteration = 0
        self.errors_in_row = 0

    def add_to_state(self, state):
        self.state.append(state)
        self.iteration += 1
        self.errors_in_row += 1
        if self.errors_in_row > 20:
            return False
        return True

    def clear(self):
