<?php

// Set the path to the YAML file
$filePath = "data.yaml";

// Read the contents of the file into a string
$fileContents = file\_get\_contents($filePath);

// Parse the YAML string into an array
$data = yaml\_parse($fileContents);

// Iterate through the groups in the array
foreach ($data as $group) {
 // Find duplicate roles in the group
