Certainly! Here's an example of a quicksort implementation in C++:


```cpp#include <iostream>
#include <algorithm>

void quicksort(int arr[], int n) {
  int i, j, temp;
  for (i = 0; i < n - 1; i++) {
    for (j = i + 1; j < n; j++) {
      if (arr[j] > arr[i]) {
        temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
      }
    }
  }
}

int main() {
  int arr[5]; // initial array
  for (int i = 0; i < 5; i++) {
    arr[i] = i;
  }
  quicksort(arr, 5);
  for (int i = 0; i < 5; i++) {
    std::cout << arr[i] << " ";
  }
  return 0;
}
```

This implementation of quicksort uses a bubble sort algorithm to sort the array in ascending order by repeatedly swapping the elements in the array such that the largest element becomes the last element. The quicksort function takes an array of integers as input and the size of the array as input and sorts the array using the bubble sort algorithm.

