Here's an example Go program that demonstrates how to split a file into 4KiB chunks:

package main

import (
"fmt"
"io"
"os"
)

func splitFile(filePath string) error {
// Open the file for reading
f, err := os.Open(filePath)
if err!= nil {
return err
}
defer f.Close()

// Get the file size
fileSize := f.GetSize()

// Calculate the number of 4KiB chunks
numChunks := (fileSize + 4095) / 4096

// Create the chunks
chunks := make([][]byte, numChunks)
for i := 0; i < numChunks; i++ {
chunkSize := 4096
if i+1 < numChunks && (fileSize+chunkSize)%4096 == 0 {
chunkSize = 4096
}
// Read the chunk from the file
chunks[i], err = ReadAll(f, chunkSize)
if err!= nil {
return err
}
}

// Create the output files
outputFiles := make([]string, numChunks)
for i := 0; i < numChunks; i++ {
outputFiles[i] = filePath + fmt.Sprintf("/chunk%d", i)
}

// Write the chunks to the output files
for i := 0; i < numChunks; i++ {
chunk := chunks[i]
// Create the directory for the chunk if it doesn't exist
_, err := os.Stat(outputFiles[i])
if err!= nil &&!os.IsExist(err) {
err = os.MkdirAll(outputFiles[i], 0777)
}
// Write the chunk to the output file
err = ioutil.WriteFile(outputFiles[i], chunk, 0644)
if err!= nil {
return err
}
}

return nil
}

