```xml
<!DOCTYPE html>
<html>
  <head>
    <title>TODO List</title>
  </head>
  <body>
    <h1>TODO List</h1>
    <form>
      <input type="text" id="new-item" placeholder="Add new item...">
      <button type="submit" onclick="addItem()">Add</button>
    </form>
    <ul id="todo-list"></ul>

    <script>
      function addItem() {
        var item = document.getElementById("new-item").value;
        var li = document.createElement("li");
        li.innerText = item;
        var deleteButton = document.createElement("button");
        deleteButton.innerText = "Delete";
        deleteButton.onclick = function() {
          var list = document.getElementById("todo-list");
          list.removeChild(this.parentNode);
        };
        li.appendChild(deleteButton);
        var checkbox = document.createElement("input");
        checkbox.type = "checkbox";
        checkbox.checked = true;
        checkbox.onchange = function() {
          if (this.checked) {
            li.style.backgroundColor = "green";
          } else {
            li.style.backgroundColor = "grey";
          }
        };
        li.appendChild(checkbox);
        var ul = document.getElementById("todo-list");
        ul.appendChild(li);
      }
    </script>
  </body>
</html>
```

This file creates a simple form with a text input for adding new items to the list, and a button to add them. The list items are added dynamically using JavaScript, and each one contains a checkbox for marking the item as complete, and a delete button for removing the item from the list. The CSS styles are not included in this file, but you can add them to make the list look the way you want.

To get an API response in Unity, you can use the built-in `UnityWebRequest` class. Here's an example of how to use it to get a JSON response from an API:
```csharp
using UnityEngine;
using UnityWebRequest;

public class GetAPIResponse : MonoBehaviour
{
    public string apiUrl = "https://example.com/api/endpoint";

    private IEnumerator GetAPI()
    {
        UnityWebRequest www = UnityWebRequest.Get(apiUrl);

        yield return www.SendWebRequest();

        if (www.isNetworkError || www.isHttpError)
        {
            Debug.Log(www.error);
        }
        else
        {
            string json = www.downloadHandler.text;
            Debug.Log(json);
        }
    }
}
```
In this example, `apiUrl` is the URL of the API endpoint you want to call. The `GetAPI()` method sends a GET request to the API using `UnityWebRequest.Get()`, and waits for the response using `SendWebRequest()`. If there's an error, it logs the error message using `Debug.Log()`. Otherwise, it logs the JSON response.

Here is an example VHDL program that generates a simple square wave using a D flip-flop:

library IEEE;
use IEEE.STD\_LOGIC\_1164.ALL;

entity square\_wave is
    Port ( clk : in  STD\_LOGIC;
           reset : in  STD\_LOGIC;
           square\_out : out  STD\_LOGIC);
end square\_wave;

architecture Behavioral of square\_wave is
    component D\_FF is
        Port ( D : in  STD\_LOGIC;
               clk : in  STD\_LOGIC;
               reset : in  STD\_LOGIC;
               Q : out  STD\_LOGIC);
    end component;

    signal Q : STD\_LOGIC;
begin
    U1: D\_FF port map (D => Q, clk => clk, reset => reset, Q => Q);
    square\_out <= Q;
end Behavioral;

program main is
    Port ( clk : in  STD\_LOGIC;
           reset : in  STD\_LOGIC;
           square\_out : out  STD\_LOGIC);
begin
    U2: square\_wave port map (clk => clk, reset => reset, square\_out => square\_out);
    wait for 10 ns;
    reset <= '1';
    wait for 10 ns;
    reset <= '0';
    wait for 10 ns;
end program main;

