Here is a sample Photoshop script written in JavaScript (JSX) that checks for smart links in the current file, records the transformations applied to the linked layers, creates new layers in a new folder with the same name as the smart link, and applies the same transformations to the newly created layers:
```php
// Check for smart objects in the current document
var smartObjects = app.activeDocument.layers.filter(layer => layer.kind === LayerKind.SMART_OBJECT);

// Record the transformations applied to the smart object
var smartObjectTransformations = [];
smartObjects.forEach(smartObject => {
  smartObjectTransformations.push(smartObject.transform);
});

// Create a new folder with the same name as the smart link
var smartLinkName = smartObjects[0].name.split('.')[0]; // Get the name of the smart link
var smartLinkFolder = new Folder(Path.join(app.activeDocument.path, smartLinkName));

// Create a new layer for each smart object transformation
var smartObjectLayers = [];
for (var i = 0; i < smartObjectTransformations.length; i++) {
  var smartObjectLayer = new Layer(smartLinkFolder, Path.join(smartLinkName, 'Layer ' + (i + 1)));
  smartObjectLayers.push(smartObjectLayer);
  smartObjectLayer.transform = smartObjectTransformations[i];
}

// Apply the same transformations to the newly created layers
var targetLayers = app.activeDocument.layers;
for (var i = 0; i < smartObjectLayers.length; i++) {
  var targetLayer = targetLayers[i];
  if (targetLayer.kind === LayerKind.SMART_OBJECT) {
    var smartObject = app.activeDocument.layers.filter(layer => layer.kind === LayerKind.SMART_OBJECT)[0];
    smartObjectLayer = smartObjectLayers[i];
    smartObjectLayer.transform = smartObject.transform;
    targetLayer.addLayer(smartObjectLayer);
  }
}
```
