```scss
import java.util.HashSet;
import java.util.Set;

public class FibonacciHash {
    public static void main(String[] args) {
        Set<Integer> fibonacci = new HashSet<>();
        fibonacci.add(0);
        fibonacci.add(1);
        fibonacci.add(1);

        for (int i = 2; i < 20; i++) {
            int next = fibonacci.lastElement() + fibonacci.iterator().next();
            fibonacci.add(next);
        }

        for (int i = 0; i < 20; i++) {
            System.out.print(fibonacci.get(i) + " ");
        }
    }
}
```

