```scss
// Set the speed and acceleration of the boat
float speed = 20;
float accel = 10;

// Set the steering sensitivity
float steeringSensitivity = 0.1;

// Handle input from the joystick
void HandleJoyInput(float inputs) {
    // Calculate the desired direction of the boat
    float desiredDirection = inputs * steeringSensitivity;

    // Set the motor speeds based on the desired direction
    if (desiredDirection > 0) {
        motorSteering = 100;
        motorAcceleration = accel;
    } else if (desiredDirection < 0) {
        motorSteering = -100;
        motorAcceleration = -accel;
    } else {
        motorSteering = 0;
        motorAcceleration = 0;
    }

    // Set the boat's speed based on the motor speed
    speed = motorSpeed;
}

// Handle motor input from the player
void HandleMotorInput(float inputs) {
    // Set the motor speed based on the input
    motorSpeed = inputs;

    // Limit the motor speed to the maximum and minimum values
    motorSpeed = min(max(motorSpeed, 0), speed);
}

// Update the boat's position and velocity
void UpdateBoat() {
    // Calculate the new position and velocity based on the motor speed
    float newPosition = speed * (cos(motorSteering) * cos(motorSpeed) - sin(motorSteering) * sin(motorSpeed));
    float newVelocity = speed * (sin(motorSteering) * cos(motorSpeed) + cos(motorSteering) * sin(motorSpeed));

    // Set the boat's new position and velocity
    boatPosition = newPosition;
    boatVelocity = newVelocity;
}
```
