int waiting_time = 0;

void enqueue(int arrival_time, int burst_time) {
    jobs[tail].arrival_time = arrival_time;
    jobs[tail].burst_time = burst_time;
    jobs[tail].priority = 0;
    tail++;
    if (tail == 10) {
        tail--;
    }
}

void preempt(int i) {
    jobs[i].priority = 1;
    while (jobs[head].priority < jobs[i].priority) {
        // wait for job with higher priority to finish
        head++;
        if (head == tail) {
            head--;
        }
    }
    jobs[head].arrival_time = 0;
    jobs[head].burst_time = jobs[i].burst_time;
    head++;
    turnaround_time = 0;
    waiting_time = 0;
}

