	regex := `^[a-zA-Z0-9!@#$%^&*()]*[0-9]+[a-zA-Z!@#$%^&*()]{8,}$`
	matched, err := regexp.MatchString(regex, str)
	if err!= nil {
		return false
	}
	if!matched {
		return false
	}

	// Check if it doesn't contain'or "
	if strContainsSpecialChars := strings.Contains(str, "'") || strings.Contains(str, `"`) {
		return false
	}

	// Check if it doesn't contain sequential or repeating characters
	str = strings.Replace(str, "1234", "1234", -1)
	if strings.Contains(str, "1234") {
		return false
	}
	str = strings.Replace(str, "abcdefghijklmnopqrstuvwxyz", "abcdefghijklmnopqrstuvwxyz", -1)
	if strings.Contains(str, "abcdefghijklmnopqrstuvwxyz") {
		return false
	}
	str = strings.Replace(str, "abcdefghijklmnopqrstuvwxyz123456789", "abcdefghijklmnopqrstuvwxyz123456789", -1)
	if strings.Contains(str, "abcdefghijklmnopqrstuvwxyz1234") {
		return false
	}

	return true
}

